:root{--ink:#10243a;--blue:#2166d1;--bg:#f4f7fb;--card:#fff;--muted:#61738a;--line:#dbe3ed;--good:#157c58;--warn:#b55a00}*{box-sizing:border-box}body{margin:0;font:14px Inter,ui-sans-serif,system-ui,sans-serif;color:var(--ink);background:var(--bg)}header{height:64px;background:#102d4d;color:white;display:flex;align-items:center;justify-content:space-between;padding:0 30px}.brand{font-weight:750;font-size:20px}.brand b{color:#69d7c0}.shell{max-width:1280px;margin:28px auto;padding:0 22px}.login{max-width:420px;margin:10vh auto;background:white;border-radius:14px;padding:32px;box-shadow:0 14px 38px #1232}.login h1{margin-top:0}.login label{display:block;font-weight:650;margin:16px 0 5px}input,select,button{font:inherit}input,select{width:100%;padding:10px;border:1px solid var(--line);border-radius:7px;background:white}button{padding:10px 14px;border:0;border-radius:7px;background:var(--blue);color:white;font-weight:650;cursor:pointer}button.secondary{color:var(--ink);background:#e8eff8}.bar{display:flex;gap:12px;align-items:center}.bar select{width:220px}.tabs{display:flex;gap:8px;margin:22px 0}.tabs button{background:transparent;color:var(--muted)}.tabs button.active{background:#dce9ff;color:#12458e}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:18px}.wide{grid-column:span 8}.side{grid-column:span 4}.full{grid-column:1/-1}h2{font-size:16px;margin:0 0 14px}h3{font-size:14px;margin:18px 0 8px}.metric{font-size:27px;font-weight:740}.muted{color:var(--muted)}.map{height:270px;border-radius:9px;background:linear-gradient(135deg,#cde7e2,#dce8f7);position:relative;overflow:hidden}.map:before{content:'Local PMTiles map • network view';position:absolute;inset:0;display:grid;place-items:center;color:#54718a;font-weight:650}.pin{position:absolute;width:14px;height:14px;border-radius:50%;background:#e34d42;border:2px solid white;box-shadow:0 1px 4px #567}.pin:nth-child(2){left:31%;top:42%}.pin:nth-child(3){left:65%;top:58%;background:#1769d1}.pin:nth-child(4){left:50%;top:25%;background:#157c58}table{width:100%;border-collapse:collapse}th{text-align:left;font-size:11px;text-transform:uppercase;color:var(--muted)}th,td{padding:10px;border-bottom:1px solid var(--line)}.pill{font-size:12px;border-radius:999px;padding:4px 8px;background:#e9f8f2;color:var(--good);font-weight:650}.exception{background:#fff0e3;color:var(--warn)}.work{padding:10px;border-left:3px solid #2c70d5;background:#f8fbff;margin:8px 0;border-radius:5px}.timeline{border-left:2px solid #b7c8dc;margin:8px 0 8px 6px;padding-left:16px}.timeline div{margin:11px 0}.notice{padding:11px;border-radius:7px;background:#fff0e3;color:#824600;margin-top:12px}.hidden{display:none}@media(max-width:750px){.wide,.side{grid-column:1/-1}.grid{display:block}.card{margin-bottom:12px}.bar{flex-wrap:wrap}}
</style></head><body><header><div class="brand">Relay<b>Lab</b> <span class="muted" style="color:#bad0e9;font-size:12px">SAMPLE NETWORK</span></div><div id="head" class="hidden"><span id="person"></span> <button class="secondary" onclick="logout()">Sign out</button></div></header><main class="shell"><section id="login" class="login"><h1>Welcome back</h1><p class="muted">Sign in to manage clinical sample custody and delivery.</p><label for="username">Username</label><input id="username" autocomplete="username" placeholder="Administrator username"><label for="password">Password</label><input id="password" type="password" autocomplete="current-password" placeholder="Password"><p id="loginError" class="notice hidden" role="alert"></p><button style="width:100%;margin-top:20px" onclick="login()">Sign in securely</button></section><section id="app" class="hidden"><div class="bar"><strong id="welcome"></strong><span class="muted">Working as</span><label class="hidden" for="role">Active role</label><select id="role" onchange="switchRole()"></select><button class="secondary" onclick="refresh()">Refresh</button></div><nav class="tabs" aria-label="Dashboard sections"><button class="active" onclick="show('overview',this)">Overview</button><button onclick="show('work',this)">My work</button><button onclick="show('requests',this)">Request sample</button><button onclick="show('audit',this)">Audit trail</button></nav><div id="overview"><div class="grid"><article class="card side"><h2>Network health</h2><div class="metric" id="locationCount">0</div><span class="muted">active network locations</span><h3>Serviceability calculation</h3><span class="pill">Published version <span id="version">1</span></span></article><article class="card wide"><h2>Live network map</h2><div class="map" aria-label="Live map using local PMTiles assets"><i class="pin"></i><i class="pin"></i><i class="pin"></i></div><p class="muted">Routes, nodes, laboratories, and current courier locations are shown from local map assets.</p></article><article class="card wide"><h2>Samples in operations</h2><table><thead><tr><th>Sample</th><th>Status</th><th>Custodian</th><th>Location freshness</th></tr></thead><tbody id="samples"><tr><td colspan="4" class="muted">No active samples yet.</td></tr></tbody></table></article><article class="card side"><h2>Exceptions</h2><div id="exceptions" class="muted">No active exceptions.</div><h3>Monitoring</h3><p class="muted">Dispatchers can monitor samples, workers, nodes, laboratories, routes, and delays from this operations view.</p></article></div></div><div id="work" class="hidden"><article class="card full"><h2>Current work</h2><div id="pending"></div><h3>In progress</h3><div id="progress"></div><h3>Completed work</h3><div id="completed"></div></article></div><div id="requests" class="hidden"><article class="card" style="max-width:650px"><h2>Check serviceability</h2><p class="muted">This dry run never creates a request, sample, journey, assignment, or reservation.</p><div class="grid"><label class="side">Latitude<input id="lat" value="51.5074"></label><label class="side">Longitude<input id="lng" value="-0.1278"></label><label class="side">Sample type<select id="sampleType"></select></label><label class="side">Delivery deadline<input id="deadline" type="datetime-local"></label></div><button onclick="check()">Check serviceability</button><div id="serviceResult" aria-live="polite"></div></article></div><div id="audit" class="hidden"><article class="card full"><h2>Search audit history</h2><div class="bar"><input id="auditQuery" placeholder="Search action or item"><button onclick="audit()">Search audit trail</button></div><div id="auditRows" class="timeline"></div></article></div></section></main><script>
let token='',activeRole='',boot={}; const api=async(path,body,method='POST')=>{let r=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json','Authorization':'Bearer '+token,'X-Active-Role':activeRole},body:method==='GET'?undefined:JSON.stringify(body||{})});let j=await r.json();if(!r.ok)throw j;return j};function login(){api('authenticate-user',{username:username.value,password:password.value}).then(x=>{token=x.token;activeRole=x.activeRole;localStorage.setItem('relayToken',token);refresh()}).catch(e=>{loginError.textContent=e.error||'Unable to sign in';loginError.classList.remove('hidden')})}function logout(){localStorage.removeItem('relayToken');token='';app.classList.add('hidden');head.classList.add('hidden');login.classList.remove('hidden')}function refresh(){api('ui/bootstrap',null,'GET').then(x=>{boot=x;login.classList.add('hidden');app.classList.remove('hidden');head.classList.remove('hidden');person.textContent=x.user.fullName||x.user.username;welcome.textContent='Hello, '+(x.user.fullName||x.user.username);role.innerHTML=x.user.roles.map(r=>`<option ${r===activeRole?'selected':''}>${r}</option>`).join('');sampleType.innerHTML=x.sampleTypes.map(t=>`<option value="${t.sampleTypeId}">${t.name}</option>`).join('');locationCount.textContent=x.locations.filter(l=>l.active).length;version.textContent=x.serviceabilityVersion;loadOps();loadWork()}).catch(()=>logout())}function switchRole(){activeRole=role.value;api('select-active-role',{role:activeRole}).then(refresh).catch(e=>alert(e.error))}function loadOps(){api('read-operations-state',{}).then(x=>{samples.innerHTML=x.samples.length?x.samples.map(s=>`<tr><td>${s.sampleId.slice(0,8)}</td><td><span class="pill">${s.status}</span></td><td>${s.currentHolderId?.slice(0,8)||'Awaiting custody'}</td><td>${s.locationStale?'Stale':'Current'}</td></tr>`).join(''):'<tr><td colspan="4" class="muted">No active samples yet.</td></tr>';exceptions.innerHTML=x.exceptions.length?x.exceptions.map(e=>`<div class="pill exception">${e.exception.reason}</div>`).join(''):'No active exceptions.'}).catch(()=>{})}function loadWork(){api('list-role-work',{role:activeRole}).then(x=>{let f=a=>a.length?a.map(w=>`<div class="work"><b>${w.kind}</b> · ${w.status}<br><span class="muted">${w.sampleId||w.journeyId||''}</span>${w.status==='offered'?` <button onclick="accept('${w.assignmentId}')">Accept assignment</button>`:''}</div>`).join(''):'<p class="muted">None.</p>';pending.innerHTML=f(x.pending);progress.innerHTML=f(x.inProgress);completed.innerHTML=f(x.completed)}).catch(()=>{})}function accept(id){api('accept-assignment',{assignmentId:id,idempotencyKey:crypto.randomUUID()}).then(loadWork).catch(e=>alert(e.error))}function check(){let d=new Date(deadline.value).toISOString();api('check-serviceability',{origin:{latitude:+lat.value,longitude:+lng.value},originType:'home',sampleTypeId:sampleType.value,requestedAt:new Date().toISOString(),deliveryDeadline:d}).then(x=>serviceResult.innerHTML=`<p class="notice">${x.serviceable?'Serviceable: '+x.reason:'Not serviceable: '+x.reason}</p>`).catch(e=>serviceResult.innerHTML=`<p class="notice">${e.error}</p>`)}function audit(){api('search-audit-trail',{query:auditQuery.value,limit:100}).then(x=>auditRows.innerHTML=x.entries.length?x.entries.map(e=>`<div><b>${e.action}</b> · ${e.entityType}<br><span class="muted">${e.occurredAt} · ${e.role}</span></div>`).join(''):'<p class="muted">No matching audit records.</p>').catch(e=>auditRows.innerHTML=e.error)}function show(id,b){['overview','work','requests','audit'].forEach(x=>document.getElementById(x).classList.toggle('hidden',x!==id));document.querySelectorAll('.tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active')}token=localStorage.getItem('relayToken')||'';if(token)refresh();
</script></body></html>"}

{"command":"create","path":"/workspace/app-setup/reset.sh","security_risk":"MEDIUM","summary":"Create idempotent application reset script","file_text":"#!/usr/bin/env bash
# The application uses a durable, application-owned JSON store. Writing the
# empty structure materializes every durable collection before the next start.
mkdir -p /workspace/data
cat > /workspace/data/state.json <<'JSON'
{
  "users": {}, "types": {}, "locations": {}, "connections": {},
  "samples": {}, "journeys": {}, "assignments": {}, "handoffs": {},
  "audit": [], "nextEvent": 1, "sessions": {}, "idempotency": {}
}
JSON
"}

