{"command":"create","path":"/workspace/cmd/lab/main_test.go","security_risk":"MEDIUM","summary":"Add response envelope contract unit test","file_text":"package main

import (
	"encoding/json"
	"net/http/httptest"
	"testing"
)

func TestSuccessResponseUsesDataEnvelope(t *testing.T) {
	recorder := httptest.NewRecorder()
	respond(recorder, 201, map[string]string{"sampleId": "sample-1"})
	if recorder.Code != 201 {
		t.Fatalf("status = %d, want 201", recorder.Code)
	}
	var body map[string]map[string]string
	if err := json.Unmarshal(recorder.Body.Bytes(), &body); err != nil {
		t.Fatal(err)
	}
	if len(body) != 1 || body["data"]["sampleId"] != "sample-1" {
		t.Fatalf("response = %#v, want data envelope", body)
	}
}

func TestReadinessIsNotWrapped(t *testing.T) {
	a := &App{}
	recorder := httptest.NewRecorder()
	a.ready(recorder, httptest.NewRequest("GET", "/ready", nil))
	if recorder.Body.String() != "{\"status\":\"ready\"}\n" {
		t.Fatalf("readiness body = %q", recorder.Body.String())
	}
}
"}
